public class KOMEProgressionCoherencePassTest {
    private static KOMEProgressionGoodsValue.Matcher oldMatcher;
    // Plain JUnit cannot initialize Forge's ore dictionary without LaunchClassLoader.
    // Pricing still uses real native entries/costs/stack counts; matching alone is headless.
    @org.junit.BeforeClass public static void headlessTradeMatching(){oldMatcher=KOMEProgressionGoodsValue.matcher;KOMEProgressionGoodsValue.matcher=(entry,stack)->{ItemStack offered=entry.createTradeItem();return offered.getItem()==stack.getItem()&&(offered.getItemDamage()==32767||offered.getItemDamage()==stack.getItemDamage());};}
    @org.junit.AfterClass public static void restoreTradeMatching(){KOMEProgressionGoodsValue.matcher=oldMatcher;}
    @Test public void onlyCurrentLiegeConfersRankAndAnnouncesOnceWithoutGift()throws Exception {
        try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){
            s.ready();KOMESerfKnightStabilizationTest.TrialCaptain liege=KOMESerfKnightStabilizationTest.captain(s);s.state.setLiege(KOMEProgressionNpcRankService.referenceOf(liege));
            KOMEProgressionAnnouncements.Sender previous=KOMEProgressionAnnouncements.sender;List<String> messages=new ArrayList<String>();KOMEProgressionAnnouncements.sender=messages::add;
            try{assertFalse(KOMESerfdomMasterService.conferKnighthood(s.f.player,s.f.data,s.master).success);assertTrue(KOMESerfdomMasterService.conferKnighthood(s.f.player,s.f.data,liege).success);assertEquals(1,messages.size());assertTrue(messages.get(0).contains(KOMEFactionProgressionTitles.title("rohan",KOMEProgressionRank.KNIGHT)));assertFalse(s.state.hasPartingGift());s.p.readFromNBT(s.p.writeToNBT());assertFalse(KOMESerfdomMasterService.conferKnighthood(s.f.player,s.f.data,liege).success);assertEquals(1,messages.size());}finally{KOMEProgressionAnnouncements.sender=previous;}
        }
    }
    @Test public void promotionPolicyNeverAnnouncesRefreshFactionOnlyOrAdminRepair(){assertFalse(KOMEProgressionAnnouncements.isPromotion(KOMEProgressionRank.KNIGHT,KOMEProgressionRank.KNIGHT,false));assertFalse(KOMEProgressionAnnouncements.isPromotion(KOMEProgressionRank.SERF,KOMEProgressionRank.KNIGHT,true));assertFalse(KOMEProgressionAnnouncements.isPromotion(KOMEProgressionRank.LORD,KOMEProgressionRank.SERF,false));}
    @Test public void completedTrialDoesNotRequireLivingFormerMasterForDirectConferral()throws Exception{try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){s.ready();lotr.common.entity.npc.LOTREntityNPC liege=s.liege();assertTrue(KOMESerfKnightService.handleNpcDeath(s.state,s.master.getUniqueID().toString(),false,11));assertFalse(s.state.getSerfdomMaster().isSet());assertTrue(KOMEProgressionTrackerSnapshot.project(s.f.player,s.p).objective.contains("Liege"));assertFalse(KOMEProgressionSummary.text(s.p,"Rohan","rohan").contains("Next: Find a Master"));assertTrue(KOMEProgressionNpcInteractionService.interact(s.f.player,s.f.data,liege));assertEquals(KOMEProgressionRank.KNIGHT,s.p.getCanonicalRank());}}
    @Test public void failureReleasesLiegeKeepsDutiesAndPersistsNpcSpecificTwentyMinutes()throws Exception {
        LongSupplier old=KOMESerfKnightProgression.failureClock;KOMESerfKnightProgression.failureClock=()->100000L;
        try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){
            s.ready();KOMEProgressionNpcRef failed=s.state.getLiege();s.state.setTrialCompleted();KOMESerfKnightTrialAssignment a=s.state.getTrialAssignment();s.state.setTrial(a);
            KOMEProgressionEncounterCleanup.failTrial(s.f.data,s.f.world,s.state);
            assertFalse(s.state.hasLiege());assertNull(s.state.getTrialAssignment());assertEquals("",s.state.getActiveAssignmentKind());assertTrue(KOMESerfKnightService.allDutiesComplete(s.state));assertEquals(1200000,s.state.failedLiegeRemaining(failed,100000));
            s.p.readFromNBT(s.p.writeToNBT());assertEquals(1200000,s.state.failedLiegeRemaining(failed,100000));assertEquals(s.f.player.id.toString(),s.state.failures().get(0).getString("Player"));
            KOMEProgressionNpcRef other=new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Other lord","rohan",failed.dimension,failed.x,failed.y,failed.z);assertEquals(0,s.state.failedLiegeRemaining(other,100000));assertEquals(0,s.state.failedLiegeRemaining(failed,1300000));
            assertFalse(KOMESerfKnightService.canRequestTrialFromProspectiveLiege(s.state,failed,11,s.f.player.id));assertTrue(KOMESerfKnightService.canRequestTrialFromProspectiveLiege(s.state,other,11,s.f.player.id));assertFalse(KOMESerfKnightService.canRequestTrialFromProspectiveLiege(s.state,other,10,s.f.player.id));s.state.setLiege(failed);assertFalse(KOMESerfKnightService.assignTrial(s.state,new Random(1),11,s.f.player.id).success);s.state.leaveLiege();
        }finally{KOMESerfKnightProgression.failureClock=old;}
    }
    @Test public void provisionGenerationAlwaysHasThreeOrFourDistinctTypesAndDrink(){
        List<KOMESerfProvisioningAssignment.Candidate> food=new ArrayList<KOMESerfProvisioningAssignment.Candidate>();for(int i=0;i<6;i++)food.add(new KOMESerfProvisioningAssignment.Candidate("food"+i,i,0,i%2==0?64:1,"Food"));food.add(food.get(0));
        for(int i=0;i<250;i++){KOMESerfProvisioningAssignment a=KOMESerfProvisioningAssignment.generate(food,Collections.singletonList(new KOMESerfProvisioningAssignment.Candidate("water",99,0,1,"Water")),Collections.singletonList("MUG"),new Random(i));assertTrue(a.foods.size()+1>=3&&a.foods.size()+1<=4);Set<String> seen=new HashSet<String>();for(KOMESerfProvisioningAssignment.Requirement r:a.foods)assertTrue(seen.add(r.itemKey));assertTrue(seen.add(a.drink.itemKey));assertTrue(a.drink.isDrink());}
    }
    @Test public void smallProvisionPoolReducesSafelyRatherThanDuplicateGoods(){KOMESerfProvisioningAssignment a=KOMESerfProvisioningAssignment.generate(Collections.singletonList(new KOMESerfProvisioningAssignment.Candidate("bread",1,0,64,"Bread")),Collections.singletonList(new KOMESerfProvisioningAssignment.Candidate("water",2,0,1,"Water")),Collections.singletonList("MUG"),new Random(1));assertEquals(1,a.foods.size());}
    @Test public void everyProfessionUsesThreeOrFourConservativelyAccessibleNonfoodGoods()throws Exception{
        try(KOMEProgressionGoodsFixture fixture=new KOMEProgressionGoodsFixture()){
        for(KOMESerfMaterialProfile profile:KOMESerfMaterialProfile.values()){
            List<KOMESerfProfessionAssignment.Candidate> pool=KOMESerfProfessionCatalog.candidatesFor(profile,"rohan");assertTrue(profile.name(),pool.size()>=3);
            for(KOMESerfProfessionAssignment.Candidate c:pool)assertTrue(c.key,KOMEProgressionGoodsEligibility.profession(new ItemStack(Item.getItemById(c.itemId),1,c.damage)));
            for(int i=0;i<20;i++){KOMESerfProfessionAssignment a=KOMESerfProfessionAssignment.generate("general_labor","Worker",profile.key,pool,new Random(i));assertTrue(a.requirements.size()>=3&&a.requirements.size()<=4);}
        }
        assertFalse(KOMEProgressionGoodsEligibility.profession(new ItemStack(Items.bread)));assertFalse(KOMEProgressionGoodsEligibility.profession(new ItemStack(Items.iron_sword)));assertFalse(KOMEProgressionGoodsEligibility.profession(new ItemStack(Items.diamond)));assertTrue(KOMEProgressionGoodsEligibility.profession(new ItemStack(Items.iron_ingot)));
        }
    }
    @Test public void valuationConservativelyUsesQuarterPriceAndCapsFallbackAndTotal(){assertEquals(250,KOMEProgressionGoodsValue.quote(1,10));assertEquals(10,KOMEProgressionGoodsValue.quote(Double.POSITIVE_INFINITY,10));assertEquals(0,KOMEProgressionGoodsValue.quote(.001,10));assertEquals(1000,KOMEProgressionGoodsValue.quote(80,10));assertEquals(128,KOMEProgressionGoodsValue.payment(Long.MAX_VALUE));assertEquals(0,KOMEProgressionGoodsValue.payment(-100));}
    @Test public void nativeTradeEntryStackQuantityDrivesTheActualValuation()throws Exception{
        new kome.common.KOMEAccessFixture();Item item=new Item();java.lang.reflect.Method raw=Item.itemRegistry.getClass().getDeclaredMethod("addObjectRaw",int.class,String.class,Object.class);raw.setAccessible(true);raw.invoke(Item.itemRegistry,23998,"kome:valuation_fixture",item);
        lotr.common.entity.npc.LOTRTradeEntries old=lotr.common.entity.npc.LOTRTradeEntries.GONDOR_BLACKSMITH_BUY;
        try{lotr.common.entity.npc.LOTRTradeEntries.GONDOR_BLACKSMITH_BUY=new lotr.common.entity.npc.LOTRTradeEntries(lotr.common.entity.npc.LOTRTradeEntries.TradeType.BUY,new lotr.common.entity.npc.LOTRTradeEntry(new ItemStack(item,16),8));assertEquals(125,KOMEProgressionGoodsValue.unitMilli(new ItemStack(item)));}finally{lotr.common.entity.npc.LOTRTradeEntries.GONDOR_BLACKSMITH_BUY=old;}
    }
    @Test public void cookedFoodsRequireAnActualPermittedCookingRoute()throws Exception{
        try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){
            Map recipes=net.minecraft.item.crafting.FurnaceRecipes.smelting().getSmeltingList();Map before=new HashMap(recipes);
            try{recipes.put(new ItemStack(Items.beef),new ItemStack(Items.cooked_beef));assertFalse(KOMEProgressionGoodsEligibility.provision(s.f.player,new ItemStack(Items.cooked_beef)));assertTrue(KOMEProgressionGoodsEligibility.provision(s.f.player,new ItemStack(Items.apple)));s.p.grant("baseline.cooking");assertTrue(KOMEProgressionGoodsEligibility.provision(s.f.player,new ItemStack(Items.cooked_beef)));}finally{recipes.clear();recipes.putAll(before);}
        }
    }
    @Test public void cumulativeCompensationPaysOnlyDepositsOnceAcrossReload()throws Exception {
        try(KOMEProgressionFollowupTest.NativeItems items=new KOMEProgressionFollowupTest.NativeItems();KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){
            KOMESerfProfessionAssignment.Requirement r=new KOMESerfProfessionAssignment.Requirement(KOMESerfProfessionAssignment.Candidate.runtime(Items.iron_ingot,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD),32);r.valueMilli=250;
            KOMESerfProfessionAssignment a=new KOMESerfProfessionAssignment("smith","Blacksmith","smith",Collections.singletonList(r));s.state.assignDuty(KOMESerfKnightDutyType.PROFESSION,a.writeToNBT());
            KOMEProgressionServiceRewards.materials(s.f.player,s.state,KOMESerfKnightDutyType.PROFESSION);assertEquals(0,s.drops());r.delivered=16;s.state.setDutyAssignmentData(KOMESerfKnightDutyType.PROFESSION,a.writeToNBT());KOMEProgressionServiceRewards.materials(s.f.player,s.state,KOMESerfKnightDutyType.PROFESSION);assertEquals(4,s.latest().stackSize);assertEquals(1,s.drops());
            s.p.readFromNBT(s.p.writeToNBT());KOMEProgressionServiceRewards.materials(s.f.player,s.state,KOMESerfKnightDutyType.PROFESSION);assertEquals(1,s.drops());r.delivered=32;s.state.setDutyAssignmentData(KOMESerfKnightDutyType.PROFESSION,a.writeToNBT());KOMEProgressionServiceRewards.materials(s.f.player,s.state,KOMESerfKnightDutyType.PROFESSION);assertEquals(2,s.drops());assertEquals(4,s.latest().stackSize);assertEquals(8,s.state.getDuty(KOMESerfKnightDutyType.PROFESSION).materialPaid);
        }
    }
    @Test public void activeLegacyPriceMigrationPreservesRequirementsAndRecordedDelivery()throws Exception{
        try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){
            KOMESerfProfessionAssignment.Requirement r=new KOMESerfProfessionAssignment.Requirement(KOMESerfProfessionAssignment.Candidate.runtime(Items.iron_ingot,0,KOMESerfProfessionAssignment.QuantityTier.STANDARD),32);r.delivered=7;
            NBTTagCompound n=new KOMESerfProfessionAssignment("smith","Blacksmith","smith",Collections.singletonList(r)).writeToNBT();n.getTagList("Requirements",10).getCompoundTagAt(0).removeTag("ValueMilli");s.state.assignDuty(KOMESerfKnightDutyType.PROFESSION,n);KOMEProgressionGoodsRecovery.priceLegacy(s.f.data,s.state);
            NBTTagCompound requirement=s.state.getDuty(KOMESerfKnightDutyType.PROFESSION).getAssignmentData().getTagList("Requirements",10).getCompoundTagAt(0);assertEquals(32,requirement.getInteger("Required"));assertEquals(7,requirement.getInteger("Delivered"));assertEquals(r.itemKey,requirement.getString("ItemKey"));assertTrue(requirement.hasKey("ValueMilli"));assertTrue(requirement.getInteger("ValueMilli")>0);String saved=s.state.writeToNBT().toString();KOMEProgressionGoodsRecovery.priceLegacy(s.f.data,s.state);assertEquals(saved,s.state.writeToNBT().toString());
        }
    }
    @Test public void actualRecoveryItemMetadataSurvivesTrackerReload()throws Exception {try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){s.ready();KOMESerfKnightTrialAssignment a=KOMESerfKnightTrialAssignment.create(KOMESerfKnightTrial.forId("recovery"),s.state.getLiege(),10,0);NBTTagCompound data=new NBTTagCompound();data.setTag("RecoveryItem",new ItemStack(Items.dye,1,4).writeToNBT(new NBTTagCompound()));s.state.setTrial(a.withStage(KOMESerfKnightTrialAssignment.Stage.ACTIVE,data));s.p.readFromNBT(s.p.writeToNBT());KOMEProgressionTrackerSnapshot hud=KOMEProgressionTrackerSnapshot.project(s.f.player,s.p);assertSame(Items.dye,hud.requestedItem.getItem());assertEquals(4,hud.requestedItem.getItemDamage());assertFalse(hud.hasNumericProgress());}}
    @Test public void courierHudIsTextOnlyForOutboundAndDelivered()throws Exception {try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){KOMESerfCourierAssignment a=s.courier();assertFalse(KOMEProgressionTrackerSnapshot.project(s.f.player,s.p).hasNumericProgress());a.stage=KOMESerfCourierAssignment.Stage.DELIVERED;s.state.setDutyAssignmentData(KOMESerfKnightDutyType.COURIER,a.writeToNBT());assertFalse(KOMEProgressionTrackerSnapshot.project(s.f.player,s.p).hasNumericProgress());assertTrue(KOMEProgressionTrackerSnapshot.project(s.f.player,s.p).objective.contains("report"));}}
    @Test public void escortWarningsAndRiskAreBoundedAndUseRealSeparation(){assertFalse(KOMEProgressionEscortJourney.shouldWarn(23*23,1000,0));assertFalse(KOMEProgressionEscortJourney.shouldWarn(25*25,399,0));assertTrue(KOMEProgressionEscortJourney.shouldWarn(25*25,400,0));assertEquals(0,KOMEProgressionEscortJourney.chance(false,200,1),0);assertEquals(0,KOMEProgressionEscortJourney.chance(false,127,0),0);assertTrue(KOMEProgressionEscortJourney.chance(true,1000,0)<KOMEProgressionEscortJourney.chance(false,1000,0));}
    @Test public void travelerSpeaksOnlyWhenSeparatedAndCooldownPreventsSpam()throws Exception{try(KOMEKnightCommissionGameplayTest.Session s=new KOMEKnightCommissionGameplayTest.Session()){KOMEKnightCommissionGameplayTest.TestNpc traveler=s.npc(LOTRFaction.ROHAN);traveler.ticksExisted=20;s.f.player.posX=traveler.posX+30;s.f.player.posY=traveler.posY;s.f.player.posZ=traveler.posZ;int before=s.f.player.messages.size();KOMEProgressionEscortJourney.tick(s.f.player,traveler);assertEquals(before+1,s.f.player.messages.size());KOMEProgressionEscortJourney.tick(s.f.player,traveler);assertEquals(before+1,s.f.player.messages.size());s.f.world.testWorldTime=500;s.f.player.posX=traveler.posX;KOMEProgressionEscortJourney.tick(s.f.player,traveler);assertEquals(before+1,s.f.player.messages.size());}}
    @Test public void incidentalAmbushTagNeverGrantsRequiredEncounterPersistenceOrEnemyOutline()throws Exception{try(KOMEKnightCommissionGameplayTest.Session s=new KOMEKnightCommissionGameplayTest.Session()){KOMEKnightCommissionGameplayTest.TestNpc mob=s.npc(LOTRFaction.MORDOR);mob.getEntityData().setBoolean("KOMEEscortAmbush",true);assertNull(KOMEProgressionEncounterMarker.read(mob));assertFalse(KOMEProgressionNpcRoles.protects(s.f.data,mob.getUniqueID()));assertFalse(KOMEVisualLocationService.markersFor(s.p).stream().anyMatch(m->m.role==KOMEVisualMarker.Role.ENCOUNTER_ENEMY&&m.entityUuid.equals(mob.getUniqueID().toString())));}}
    @Test public void destinationHistoryIsBoundedContextualAndPersistent(){KOMESerfKnightProgression s=new KOMESerfKnightProgression();KOMEProgressionNpcRef ref=new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Liege","rohan",100,0,64,0);for(int i=0;i<12;i++)s.variety.remember(ref,"escort",i*300,0);assertEquals(8,s.variety.write().tagCount());assertEquals(0,s.variety.penalty(ref,0,0));assertTrue(s.variety.penalty(ref,3300,0)>0);NBTTagCompound saved=s.writeToNBT();s.readFromNBT(saved);assertTrue(s.variety.penalty(ref,3300,0)>0);}
    @Test public void commissionHistoryWeightsVarietyWithoutRemovingEligibleTypes(){KOMEProgressionNpcRef ref=new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Liege","rohan",100,0,64,0);KOMEKnightCommission previous=new KOMEKnightCommission(KOMEKnightCommission.Type.RELIEF,ref);int repeats=0;for(int i=0;i<500;i++){List<KOMEKnightCommission.Type> order=KOMEProgressionVariety.order(Arrays.asList(KOMEKnightCommission.Type.values()),Collections.singletonList(previous),"rohan",new Random(i*999L));assertEquals(5,new HashSet<>(order).size());if(order.get(0)==previous.type)repeats++;}assertTrue(repeats<100);}
    @Test public void adminFinishPreservesRankAndDoesNotPayOrInventDelivery()throws Exception {try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){s.courier();assertTrue(KOMEProgressionDevelopment.finish(s.f.player).contains("ready to report"));assertEquals(KOMEProgressionRank.SERF,s.p.getCanonicalRank());assertTrue(s.state.getDuty(KOMESerfKnightDutyType.COURIER).adminForced);assertFalse(s.state.getDuty(KOMESerfKnightDutyType.COURIER).isCompleted());assertEquals(KOMESerfCourierAssignment.Stage.DELIVERED,s.active().stage);assertEquals(0,s.drops());assertEquals(1,s.f.data.centralAudit.size());assertTrue(KOMECourierService.reportToMaster(s.f.player,s.f.data,s.p));assertTrue(s.state.getDuty(KOMESerfKnightDutyType.COURIER).isCompleted());assertEquals(0,s.drops());}}
    @Test public void adminCommissionReportCannotEarnFactionServiceCredit()throws Exception {try(KOMEKnightCommissionGameplayTest.Session s=new KOMEKnightCommissionGameplayTest.Session()){KOMEKnightCommission a=s.active(KOMEKnightCommission.Type.RELIEF);assertTrue(KOMEProgressionDevelopment.finish(s.f.player).contains("ready to report"));assertFalse(a.participated);assertFalse(a.threatResolved);assertTrue(a.adminForced);assertTrue(s.p.getKnightService().report(a.liege));assertTrue(s.p.getKnightService().qualifyingTypes("rohan").isEmpty());}}
    @Test public void adminResetCleansOnlyCurrentAssignmentAndPreservesDailyCadence()throws Exception {try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){s.courier();s.state.setLastAssignmentEpochDay(10);KOMEProgressionDevelopment.reset(s.f.player);assertFalse(s.state.hasActiveAssignment());assertEquals(10,s.state.getLastAssignmentEpochDay());assertTrue(s.state.getSerfdomMaster().isSet());assertEquals(KOMEProgressionRank.SERF,s.p.getCanonicalRank());}}
    @Test public void directBoundRecoveryCancelsGuiConsumesOnceAndPromotesOnlyOnLaterReport()throws Exception {
        try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){
            s.ready();KOMESerfKnightStabilizationTest.TrialCaptain liege=s.liege();KOMESerfKnightTrialAssignment a=KOMESerfKnightTrialAssignment.create(KOMESerfKnightTrial.forId("recovery"),s.state.getLiege(),10,0);NBTTagCompound n=new NBTTagCompound();n.setTag("RecoveryItem",new ItemStack(Items.iron_ingot).writeToNBT(new NBTTagCompound()));n.setBoolean(KOMESerfKnightRecoveryService.DATA_RETRIEVED,false);s.state.setTrial(a.withStage(KOMESerfKnightTrialAssignment.Stage.ACTIVE,n));
            s.f.player.inventory.mainInventory[0]=KOMESerfKnightRecoveryService.assignedStack(s.state.getTrialAssignment(),s.f.player.id);
            net.minecraftforge.event.entity.player.EntityInteractEvent event=new net.minecraftforge.event.entity.player.EntityInteractEvent(s.f.player,liege){@Override public boolean isCancelable(){return true;}};
            new KOMEEvents().onEntityInteract(event);assertTrue(event.isCanceled());assertNull(s.f.player.inventory.mainInventory[0]);assertTrue(s.state.isTrialCompleted());assertEquals(KOMEProgressionRank.SERF,s.p.getCanonicalRank());assertEquals(1,Collections.frequency(s.f.world.playedSounds,"mob.horse.leather"));assertFalse(KOMESerfKnightRecoveryService.deliver(s.f.player,s.p,liege));assertEquals(1,Collections.frequency(s.f.world.playedSounds,"mob.horse.leather"));
        }
    }
    @Test public void activeServiceBookContainsOnlyCurrentCommissionDetails()throws Exception {try(KOMEKnightCommissionGameplayTest.Session s=new KOMEKnightCommissionGameplayTest.Session()){KOMEKnightCommission a=s.active(KOMEKnightCommission.Type.STOLEN_GOODS);a.goods.add(new KOMEKnightCommission.Goods(String.valueOf(Item.itemRegistry.getNameForObject(Items.iron_ingot)),0,1));KOMEProgressionRankSummary summary=KOMEProgressionRankSummary.project(s.p,150,"rohan");assertEquals(KOMEKnightCommissionPresentation.title(a.type),summary.activityTitle);assertTrue(summary.activityObjective.contains("Property:"));for(KOMEKnightCommission.Type t:KOMEKnightCommission.Type.values())if(t!=a.type)assertFalse(summary.activityObjective.contains(KOMEKnightCommissionPresentation.title(t)));assertTrue(summary.activityObjective.contains("Report personally"));}}
    @Test public void directSealedPropertyDoesNotWaitForInventoryTrackerRefresh()throws Exception{try(KOMEKnightCommissionGameplayTest.Session s=new KOMEKnightCommissionGameplayTest.Session()){lotr.common.entity.npc.LOTREntityNPC liege=KOMEKnightCommissionInteractionTest.captain(s);KOMEKnightCommission a=new KOMEKnightCommission(KOMEKnightCommission.Type.STOLEN_GOODS,s.p.getSerfKnightProgression().getLiege());a.stage=KOMEKnightCommission.Stage.ACTIVE;a.threatResolved=true;a.goods.add(new KOMEKnightCommission.Goods(String.valueOf(Item.itemRegistry.getNameForObject(Items.iron_ingot)),0,1));assertTrue(s.p.getKnightService().offer(a));s.f.player.inventory.mainInventory[0]=KOMEKnightCommissionService.property(a,s.f.player.id);assertTrue(KOMEKnightCommissionService.directPropertyHandover(s.f.player,liege));assertNull(s.f.player.inventory.mainInventory[0]);assertNull(s.p.getKnightService().assignment());assertEquals(1,s.p.getKnightService().qualifyingTypes("rohan").size());assertEquals(1,Collections.frequency(s.f.world.playedSounds,"mob.horse.leather"));assertFalse(KOMEKnightCommissionService.directPropertyHandover(s.f.player,liege));}}
    @Test public void administrationCommandsRejectPlayersAndMalformedSyntaxBeforeMutation()throws Exception {try(KOMEProgressionFollowupTest.Session s=new KOMEProgressionFollowupTest.Session()){kome.common.command.KOMECommandKome command=new kome.common.command.KOMECommandKome();s.courier();for(String action:new String[]{"finishDuty","resetDuty","status","why"}){try{command.processCommand(s.f.player,new String[]{"progression",action});fail("nonoperator accepted");}catch(net.minecraft.command.WrongUsageException expected){}}assertTrue(s.state.hasActiveAssignment());s.f.player.operator=true;try{command.processCommand(s.f.player,new String[]{"progression","finishDuty","extra"});fail("invalid syntax accepted");}catch(net.minecraft.command.WrongUsageException expected){}assertTrue(s.state.hasActiveAssignment());}}
}
